const input = $input.first().json;
const request = String(input.body?.request ?? input.request ?? '').trim();
if (request.length < 12 || request.length > 1200) throw new Error('Request must contain between 12 and 1200 characters.');
const text = request.toLowerCase();
const any = (xs) => xs.some((x) => text.includes(x));
const rules = [
 { category:'access', words:['access','acceso','login','permission','permiso','repository','repositorio','password','contraseña'], id:'OPS-ACC-003', title:'Repository and system access', excerpt:'Confirm the resource, business need, and accountable approver before granting access.', fields:[['resource or repository',['repository','repositorio','github','drive','system','sistema']],['responsible approver',['approved by','aprobado por','manager','responsable','supervisor']]] },
 { category:'billing', words:['invoice','factura','billing','cobro','amount','importe','payment','pago'], id:'OPS-FIN-004', title:'Invoice discrepancy review', excerpt:'Record the invoice reference and disputed amount; finance must approve any correction.', fields:[['invoice reference',['inv-','invoice #','factura ','número']],['disputed amount',['$','usd','eur','ars','importe','amount']]] },
 { category:'technical', words:['down','unavailable','caído','no funciona','error','service','servicio','server','servidor'], id:'OPS-TEC-002', title:'Service incident response', excerpt:'Identify the affected service, impact, and start time before assigning incident severity.', fields:[['affected service',['service','servicio','server','servidor','api','website','sitio']],['business impact',['team','equipo','client','cliente','users','usuarios','delivery','entrega']]] }
];
const ranked = rules.map((rule) => ({...rule, score:rule.words.filter((word) => text.includes(word)).length})).sort((a,b) => b.score-a.score);
const found = ranked[0].score ? ranked[0] : { category:'general', id:'OPS-GEN-001', title:'General request intake', excerpt:'Confirm the objective, desired deadline, and accountable owner before routing the request.', fields:[['desired outcome',['need','necesito','request','solicito']],['desired deadline',['today','hoy','tomorrow','mañana','urgent','urgente']]] };
const missing = found.fields.filter(([, patterns]) => !patterns.some((p) => text.includes(p))).map(([label]) => label);
const urgent = any(['urgent','urgente','today','hoy','blocked','bloqueado','all users','todos los usuarios']);
const sensitive = ['access','billing'].includes(found.category);
const priority = urgent ? 'high' : missing.length === 0 ? 'medium' : 'normal';
const humanReview = sensitive || urgent;
return [{json:{request,caseId:`OPS-${Date.now().toString(36).toUpperCase()}`,category:found.category,priority,humanReview,summary:`A ${priority}-priority ${found.category} request was identified from the submitted description.`,nextAction:missing.length?`Request clarification: ${missing.join(', ')}.`:humanReview?'Send the proposed action to an accountable reviewer.':'Route the case to the operations queue.',missing,procedure:{id:found.id,title:found.title,excerpt:found.excerpt},audit:['Input length and type validated',`Matched procedure ${found.id} using explicit keywords`,`${missing.length} required field(s) missing`],engine:'deterministic-baseline-v1'}}];

const baseline = $('Deterministic baseline').first().json;
const candidate = $input.first().json;
const allowedCategories = ['access','billing','technical','general'];
const allowedPriorities = ['normal','medium','high'];
let ai = candidate.output ?? candidate;
if (typeof ai === 'string') { try { ai = JSON.parse(ai); } catch { ai = null; } }
const valid = ai && allowedCategories.includes(ai.category) && allowedPriorities.includes(ai.priority) && typeof ai.summary === 'string' && ai.summary.trim() && Array.isArray(ai.missing);
const category = valid ? ai.category : baseline.category;
const priority = valid ? ai.priority : baseline.priority;
const missing = valid ? ai.missing.slice(0, 5).map(String) : baseline.missing;
const humanReview = ['access','billing'].includes(category) || priority === 'high';
const procedures = {
 access:{id:'OPS-ACC-003',title:'Repository and system access',excerpt:'Confirm the resource, business need, and accountable approver before granting access.'},
 billing:{id:'OPS-FIN-004',title:'Invoice discrepancy review',excerpt:'Record the invoice reference and disputed amount; finance must approve any correction.'},
 technical:{id:'OPS-TEC-002',title:'Service incident response',excerpt:'Identify the affected service, impact, and start time before assigning incident severity.'},
 general:{id:'OPS-GEN-001',title:'General request intake',excerpt:'Confirm the objective, desired deadline, and accountable owner before routing the request.'}
};
const nextAction = missing.length ? `Request clarification: ${missing.join(', ')}.` : humanReview ? 'Send the proposed action to an accountable reviewer.' : 'Route the case to the operations queue.';
return [{json:{caseId:baseline.caseId,category,priority,humanReview,summary:valid?ai.summary.trim():baseline.summary,nextAction,missing,procedure:procedures[category],audit:[...baseline.audit,valid?'AI classification accepted after schema validation':'AI unavailable or invalid; deterministic classification retained',humanReview?'Human review required by deterministic safety policy':'Automatic routing allowed by deterministic safety policy'],engine:valid?'gemini-with-deterministic-policy-v1':'deterministic-fallback-v1'}}];
